// The Drik fallback against the kernel's own numbers: the same fixtures
// the Rust builder generates from the kernel, read through the coefficient
// file. This proves the fallback — the file the app ships for when the
// server is slow or unreachable — reproduces the Drik panchanga, not just
// the positions. Fixtures generated by `siddhanta-table drik-build`,
// `drik-fixtures` and `drik-sun` from the synthetic kernel (see
// apps/rust/crates/siddhanta-table/README.md): the positions are circular
// orbits, not astronomy, so the test proves the builder, the file and the
// reader agree — the real kernel's file is built where the kernel lives.
//
// Lagna and sunrise go through the Drik frame (true obliquity, rigorous
// sidereal time, −0.833° horizon) carried on the source — the shared
// solver reads the frame from the source, so the same code serves both
// systems.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { chebPositionsAt, parseChebTable } from "../src/astronomy/chebyshev";
import {
  displaySpeedAt,
  grahaAt,
  karanaAt,
  lagnaAt,
  nextNakshatraBoundary,
  nextTithiBoundary,
  sunriseSunset,
  tithiAt,
  yogaAt,
} from "../src/astronomy/siddhanta-offline";
import { drikSource, loadDrikSource } from "../src/astronomy/drik-source";

const KATHMANDU_LAT = 27.7172;
const KATHMANDU_LON = 85.324;

interface Fixture {
  jd: number;
  longitude: number[];
  speed: number[];
  ayanamsha: number;
  mean_sun_sayana: number;
  tithi: number;
  tithi_progress: number;
  nakshatra: number;
  pada: number;
  nakshatra_progress: number;
  yoga: number;
  yoga_progress: number;
  karana: number;
  karana_progress: number;
  moon_rashi: number;
  sun_rashi: number;
  lagna: number;
}

interface SunFixture {
  start_jd: number;
  sunrise_jd: number;
  sunset_jd: number;
}

function loadDrikBytes(): Uint8Array {
  const tableB64 = readFileSync(
    new URL("./fixtures/drik-2000.cheb.b64", import.meta.url),
    "utf8",
  );
  return new Uint8Array(Buffer.from(tableB64.trim(), "base64"));
}

function loadFixtures(): {
  table: ReturnType<typeof parseChebTable>;
  rows: Fixture[];
  sun: SunFixture[];
} {
  const table = parseChebTable(loadDrikBytes());
  const rows = JSON.parse(
    readFileSync(new URL("./fixtures/drik-2000.json", import.meta.url), "utf8"),
  ) as Fixture[];
  const sun = JSON.parse(
    readFileSync(new URL("./fixtures/drik-2000-sun.json", import.meta.url), "utf8"),
  ) as SunFixture[];
  return { table, rows, sun };
}

function angleClose(actual: number, expected: number, toleranceDegrees: number): void {
  let diff = ((actual - expected) % 360 + 540) % 360 - 180;
  diff = Math.abs(diff);
  assert.ok(diff <= toleranceDegrees, `expected ${actual} within ${toleranceDegrees}° of ${expected}`);
}

test("drik longitudes match the kernel, and the header carries the ayanamsha", () => {
  const { table, rows } = loadFixtures();
  // The table is version 2: the ayanamsha comes from its header, fitted
  // from the kernel, not from the Surya formula.
  assert.ok(table.ayanamsha !== undefined, "a Drik file is CHEB0002");
  // Same tolerances as the Surya test: the fit leaves under ~0.5" on every
  // body over the file's range.
  const tolerance = [0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001, 0.001];
  for (const row of rows) {
    const positions = chebPositionsAt(table, row.jd);
    assert.ok(positions !== null, `JD ${row.jd} is inside the table`);
    for (let b = 0; b < 8; b += 1) {
      angleClose(positions.longitude[b], row.longitude[b], tolerance[b]);
    }
    assert.ok(Math.abs(positions.ayanamsha - row.ayanamsha) < 0.001, `ayanamsha JD ${row.jd}`);
    assert.ok(
      Math.abs(positions.meanSunSayana - row.mean_sun_sayana) < 0.001,
      `mean Sun JD ${row.jd}`,
    );
  }
});

test("display speeds, tithi, nakshatra, yoga, karana and lagna match the kernel", () => {
  const { table, rows } = loadFixtures();
  const source = drikSource(loadDrikBytes());
  const bodies = ["sun", "moon", "mars", "mercury", "jupiter", "venus", "saturn", "rahu"] as const;
  for (const row of rows) {
    for (let b = 0; b < 8; b += 1) {
      const speed = displaySpeedAt(source, row.jd, bodies[b]);
      assert.ok(speed !== null, `JD ${row.jd} ${bodies[b]} is inside the table`);
      assert.ok(
        Math.abs(speed - row.speed[b]) < 0.005,
        `JD ${row.jd} ${bodies[b]}: ${speed} vs ${row.speed[b]}`,
      );
    }
    const positions = chebPositionsAt(table, row.jd);
    assert.ok(positions !== null);
    const sun = positions.longitude[0];
    const moon = positions.longitude[1];
    const tithi = tithiAt(sun, moon);
    assert.equal(tithi.number, row.tithi, `tithi JD ${row.jd}`);
    assert.ok(Math.abs(tithi.progress - row.tithi_progress) < 0.002, `tithi progress JD ${row.jd}`);
    const graha = grahaAt(moon);
    assert.equal(graha.nakshatra, row.nakshatra, `nakshatra JD ${row.jd}`);
    assert.equal(graha.pada, row.pada, `pada JD ${row.jd}`);
    assert.ok(
      Math.abs(graha.nakshatraProgress - row.nakshatra_progress) < 0.002,
      `nakshatra progress JD ${row.jd}`,
    );
    assert.equal(graha.rashi, row.moon_rashi, `Moon rashi JD ${row.jd}`);
    assert.equal(grahaAt(sun).rashi, row.sun_rashi, `Sun rashi JD ${row.jd}`);
    const yoga = yogaAt(sun, moon);
    assert.equal(yoga.number, row.yoga, `yoga JD ${row.jd}`);
    assert.ok(Math.abs(yoga.progress - row.yoga_progress) < 0.002, `yoga progress JD ${row.jd}`);
    const karana = karanaAt(sun, moon);
    assert.equal(karana.number, row.karana, `karana JD ${row.jd}`);
    assert.ok(Math.abs(karana.progress - row.karana_progress) < 0.002, `karana progress JD ${row.jd}`);
    const lagna = lagnaAt(source, row.jd, KATHMANDU_LAT, KATHMANDU_LON);
    assert.ok(lagna !== null);
    angleClose(lagna, row.lagna, 0.02);
  }
});

test("sunrise and sunset match the kernel for Kathmandu", () => {
  const { table, sun } = loadFixtures();
  const source = drikSource(loadDrikBytes());
  // The first fixture day starts before the table does, so its sunrise
  // (before the table's first instant) cannot be found from the file.
  const days = sun.filter((day) => day.start_jd >= table.firstJd);
  assert.ok(days.length > 0, "some fixture days are inside the table");
  for (const day of days) {
    const found = sunriseSunset(source, day.start_jd, KATHMANDU_LAT, KATHMANDU_LON);
    assert.ok(found.sunriseJd !== null, `sunrise ${day.start_jd}`);
    assert.ok(found.sunsetJd !== null, `sunset ${day.start_jd}`);
    assert.ok(
      Math.abs(found.sunriseJd - day.sunrise_jd) < 0.0014,
      `sunrise ${day.start_jd}: ${found.sunriseJd} vs ${day.sunrise_jd}`,
    );
    assert.ok(
      Math.abs(found.sunsetJd - day.sunset_jd) < 0.0014,
      `sunset ${day.start_jd}: ${found.sunsetJd} vs ${day.sunset_jd}`,
    );
  }
});

test("next tithi and nakshatra boundaries land on a real change", () => {
  const { table, rows } = loadFixtures();
  const source = drikSource(loadDrikBytes());
  const row = rows[0];
  const positions = chebPositionsAt(table, row.jd);
  assert.ok(positions !== null);
  const tithiBoundary = nextTithiBoundary(source, row.jd);
  assert.ok(tithiBoundary !== null && tithiBoundary > row.jd);
  const before = chebPositionsAt(table, tithiBoundary - 1 / 1440);
  const after = chebPositionsAt(table, tithiBoundary + 1 / 1440);
  assert.ok(before !== null && after !== null);
  assert.notEqual(
    tithiAt(before.longitude[0], before.longitude[1]).number,
    tithiAt(after.longitude[0], after.longitude[1]).number,
  );
  const nakshatraBoundary = nextNakshatraBoundary(source, row.jd);
  assert.ok(nakshatraBoundary !== null && nakshatraBoundary > row.jd);
  const nBefore = chebPositionsAt(table, nakshatraBoundary - 1 / 1440);
  const nAfter = chebPositionsAt(table, nakshatraBoundary + 1 / 1440);
  assert.ok(nBefore !== null && nAfter !== null);
  assert.notEqual(
    grahaAt(nBefore.longitude[1]).nakshatra,
    grahaAt(nAfter.longitude[1]).nakshatra,
  );
});

test("a Surya file is refused as a Drik source, and the loader reads the bundled file", async () => {
  const suryaB64 = readFileSync(
    new URL("./fixtures/chebyshev-2000.cheb.b64", import.meta.url),
    "utf8",
  );
  const suryaBytes = new Uint8Array(Buffer.from(suryaB64.trim(), "base64"));
  assert.throws(() => drikSource(suryaBytes), /CHEB0002/);

  const bundled = () => Promise.resolve(loadDrikBytes());
  const { table, rows } = loadFixtures();
  const jd = rows[0].jd;
  const source = await loadDrikSource(bundled);
  const positions = source.positionsAt(jd);
  assert.ok(positions !== null);
  // The loader reads the same file the evaluator does, so they agree
  // exactly; and both agree with the kernel's fixture to the fit error.
  const direct = chebPositionsAt(table, jd);
  assert.ok(direct !== null);
  angleClose(positions.longitude[1], direct.longitude[1], 0.000001);
  angleClose(positions.longitude[1], rows[0].longitude[1], 0.005);
});
